const searchHashtags = `-- name: SearchHashtags :many
SELECT h.tag, count(*)::int AS uses
FROM post_hashtags h
JOIN posts p ON p.id = h.post_id
WHERE p.visibility = 'public'
  AND p.moderation_status = 'approved'
  AND position(lower($1::text) in h.tag) > 0
  AND NOT EXISTS (
    SELECT 1 FROM blocks b
    WHERE (b.blocker_id = $2::text AND b.blocked_id = p.author_id)
       OR (b.blocker_id = p.author_id AND b.blocked_id = $2::text)
  )
GROUP BY h.tag
ORDER BY count(*) DESC, h.tag
LIMIT $3
`

