const suggestFriendsOfFriends = `-- name: SuggestFriendsOfFriends :many
SELECT u.id, u.display_name, u.avatar_url, count(*)::int AS mutuals
FROM follows f
JOIN follows ff ON ff.follower_id = f.followee_id
JOIN users u ON u.id = ff.followee_id
WHERE f.follower_id = $1::text
  AND ff.followee_id <> $1::text
  -- 이미 팔로우하는 사람은 뺀다.
  AND NOT EXISTS (
    SELECT 1 FROM follows mine
    WHERE mine.follower_id = $1::text AND mine.followee_id = ff.followee_id
  )
  AND NOT EXISTS (
    SELECT 1 FROM blocks b
    WHERE (b.blocker_id = $1::text AND b.blocked_id = ff.followee_id)
       OR (b.blocker_id = ff.followee_id AND b.blocked_id = $1::text)
  )
GROUP BY u.id, u.display_name, u.avatar_url
ORDER BY count(*) DESC, u.id
LIMIT $2
`

