const updatePost = `-- name: UpdatePost :execrows
UPDATE posts
SET caption = $1,
    visibility = CASE WHEN $2::boolean THEN $3::text ELSE visibility END,
    updated_at = now()
WHERE id = $4::text AND author_id = $5::text
`

type UpdatePostParams struct {
	Caption       *string
	SetVisibility bool
	Visibility    string
	ID            string
	AuthorID      string
}

// 올린 뒤 고칠 수 있는 것은 캡션과 공개범위뿐이다. 운동 기록은 그때의 사실이라 손대지 않는다.
func (q *Queries) UpdatePost(ctx context.Context, arg UpdatePostParams) (int64, error) {
	result, err := q.db.Exec(ctx, updatePost,
		arg.Caption,
		arg.SetVisibility,
		arg.Visibility,
		arg.ID,
		arg.AuthorID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
